begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;select no_plan();
select ok((select bool_and(rowsecurity) from pg_tables where schemaname='public' and tablename in ('lesson_attendance_sheets','lesson_attendance_records','attendance_events')),'All attendance tables enforce RLS');
select ok(not has_table_privilege('authenticated','public.lesson_attendance_records','insert'),'Attendance writes require checked commands');
select ok(not has_table_privilege('authenticated','public.attendance_events','select'),'Raw audit snapshots remain private');
select ok(not has_function_privilege('anon','public.prepare_attendance_sheet(uuid,uuid,uuid)','execute'),'Anonymous attendance mutation is revoked');
create temporary table academic_scope(label text primary key,id uuid);
grant select,insert on academic_scope to authenticated;
create function pg_temp.sid(text) returns uuid language sql stable as $$select id from academic_scope where label=$1$$;
create function pg_temp.day(integer) returns text language sql stable as $$select ((now() at time zone 'Asia/Tashkent')::date+$1)::text$$;
insert into auth.users(id,email,email_confirmed_at) values('99999500-0000-0000-0000-000000000001','native-attendance-owner@example.test',now()),('99999500-0000-0000-0000-000000000002','native-attendance-teacher@example.test',now()),('99999500-0000-0000-0000-000000000003','native-attendance-foreign@example.test',now());
set local role authenticated;
set local request.jwt.claim.sub='99999500-0000-0000-0000-000000000001';
insert into academic_scope values('tenant',public.create_business('Native academic integration'));
insert into academic_scope select 'branch',id from public.branches where tenant_id=pg_temp.sid('tenant') limit 1;
insert into academic_scope values('course',public.save_course(pg_temp.sid('tenant'),null,gen_random_uuid(),0,'{"name":"Academic integration course","standard_price":"750000.10","pricing_model":"monthly"}'));
insert into academic_scope values('group',public.save_study_group(pg_temp.sid('tenant'),null,gen_random_uuid(),0,jsonb_build_object('name','Original student group','course_id',pg_temp.sid('course'),'branch_id',pg_temp.sid('branch'),'start_date',pg_temp.day(-30),'capacity','1')));
insert into academic_scope values('teacher',public.save_employee(pg_temp.sid('tenant'),null,'Native integration teacher','','native-attendance-teacher@example.test','Teacher','active',pg_temp.day(0)::date,'',array[pg_temp.sid('branch')]));
insert into academic_scope values('role',(select id from public.business_roles where tenant_id=pg_temp.sid('tenant') and system_key='teacher'));
create temporary table academic_token(token text);
grant select,insert on academic_token to authenticated;
insert into academic_token select public.create_employee_invitation(pg_temp.sid('tenant'),pg_temp.sid('teacher'),pg_temp.sid('role'));
set local request.jwt.claim.sub='99999500-0000-0000-0000-000000000002';
select public.accept_employee_invitation((select token from academic_token));
set local request.jwt.claim.sub='99999500-0000-0000-0000-000000000001';
select public.set_group_teachers(pg_temp.sid('tenant'),pg_temp.sid('group'),gen_random_uuid(),1,array[pg_temp.sid('teacher')],pg_temp.sid('teacher'));
select public.change_group_status(pg_temp.sid('tenant'),pg_temp.sid('group'),gen_random_uuid(),2,'active','Activate original student group');
insert into academic_scope values('student',public.save_student(pg_temp.sid('tenant'),gen_random_uuid(),null,'{"first_name":"Original native student","phone":"9989088181"}','{}',array[pg_temp.sid('branch')]));
insert into academic_scope values('enrollment',public.create_student_enrollment(pg_temp.sid('tenant'),pg_temp.sid('group'),pg_temp.sid('student'),gen_random_uuid(),jsonb_build_object('enrollment_date',pg_temp.day(0),'effective_start_date',pg_temp.day(-10),'status','active','agreed_price','9007199254740993.12','pricing_model','monthly')));
insert into academic_scope values('lesson',public.save_lesson(pg_temp.sid('tenant'),pg_temp.sid('group'),null,gen_random_uuid(),0,jsonb_build_object('local_start',pg_temp.day(-1)||'T10:00','local_end',pg_temp.day(-1)||'T11:00','timezone','Asia/Tashkent','teacher_id',pg_temp.sid('teacher'),'title','Native attendance lesson'),'Backfilled attendance fixture'));
select is(public.attendance_sheet_details(pg_temp.sid('tenant'),pg_temp.sid('lesson'))->'rows'->0->>'status','unmarked','Preview starts Unmarked rather than Absent');
select is(public.attendance_sheet_details(pg_temp.sid('tenant'),pg_temp.sid('lesson'))->'rows'->0->>'customer_id',pg_temp.sid('student')::text,'Expected roster reuses original student identity');
set local request.jwt.claim.sub='99999500-0000-0000-0000-000000000002';
insert into academic_scope values('sheet',public.prepare_attendance_sheet(pg_temp.sid('tenant'),pg_temp.sid('lesson'),'99999500-0000-0000-0000-000000000010'));
select is(public.prepare_attendance_sheet(pg_temp.sid('tenant'),pg_temp.sid('lesson'),'99999500-0000-0000-0000-000000000010'),pg_temp.sid('sheet'),'Teacher prepare retry returns one sheet');
insert into academic_scope select 'record',id from public.lesson_attendance_records where sheet_id=pg_temp.sid('sheet');
select is((select count(*) from public.lesson_attendance_records where sheet_id=pg_temp.sid('sheet')),1::bigint,'One attendance record per original student and lesson');
select throws_ok($$select public.finalize_attendance_sheet(pg_temp.sid('tenant'),pg_temp.sid('lesson'),gen_random_uuid(),1)$$,'P0001','Mark every expected student before finalizing; Unmarked is not Absent','Unmarked roster cannot finalize');
select ok(not(public.attendance_sheet_details(pg_temp.sid('tenant'),pg_temp.sid('lesson'))::text like '%9007199254740993%'),'Teacher attendance API exposes no agreement price');
reset role;
select throws_ok($$insert into public.lesson_attendance_records(tenant_id,sheet_id,lesson_id,group_id,branch_id,customer_id,enrollment_id,updated_by) select tenant_id,sheet_id,lesson_id,group_id,branch_id,customer_id,enrollment_id,updated_by from public.lesson_attendance_records where id=pg_temp.sid('record')$$,'23505',null,'Database constraint rejects duplicate attendance identity');
set local role authenticated;
select public.save_attendance_marks(pg_temp.sid('tenant'),pg_temp.sid('lesson'),'99999500-0000-0000-0000-000000000011',1,jsonb_build_array(jsonb_build_object('record_id',pg_temp.sid('record'),'status','late','late_minutes','5','notes','Optional arrival note')));
select is(public.attendance_sheet_details(pg_temp.sid('tenant'),pg_temp.sid('lesson'))->'counts'->>'late','1','Draft saves Late status');
select is(public.attendance_sheet_details(pg_temp.sid('tenant'),pg_temp.sid('lesson'))->'rows'->0->>'late_minutes','5','Late minutes remain exact integers');
select is(public.save_attendance_marks(pg_temp.sid('tenant'),pg_temp.sid('lesson'),'99999500-0000-0000-0000-000000000011',1,jsonb_build_array(jsonb_build_object('record_id',pg_temp.sid('record'),'status','late','late_minutes','5','notes','Optional arrival note'))),pg_temp.sid('sheet'),'Identical save request is idempotent');
select throws_ok($$select public.save_attendance_marks(pg_temp.sid('tenant'),pg_temp.sid('lesson'),gen_random_uuid(),1,jsonb_build_array(jsonb_build_object('record_id',pg_temp.sid('record'),'status','present')))$$,'40001',null,'Stale version cannot overwrite saved marks');
select throws_ok($$select public.save_attendance_marks(pg_temp.sid('tenant'),pg_temp.sid('lesson'),gen_random_uuid(),2,jsonb_build_array(jsonb_build_object('record_id',gen_random_uuid(),'status','present')))$$,'42501',null,'Forged student attendance row ID is denied');
select public.finalize_attendance_sheet(pg_temp.sid('tenant'),pg_temp.sid('lesson'),gen_random_uuid(),2);
select is(public.attendance_sheet_details(pg_temp.sid('tenant'),pg_temp.sid('lesson'))->'sheet'->>'state','finalized','Teacher finalizes fully marked saved attendance');
select is(public.lesson_details(pg_temp.sid('tenant'),pg_temp.sid('lesson'))->'lesson'->>'status','scheduled','Attendance finalization does not automatically complete a lesson');
select throws_ok($$select public.save_attendance_marks(pg_temp.sid('tenant'),pg_temp.sid('lesson'),gen_random_uuid(),3,jsonb_build_array(jsonb_build_object('record_id',pg_temp.sid('record'),'status','absent')),true,'Teacher escalation')$$,'42501',null,'Teacher has no implicit finalized correction permission');
set local request.jwt.claim.sub='99999500-0000-0000-0000-000000000001';
select public.save_attendance_marks(pg_temp.sid('tenant'),pg_temp.sid('lesson'),gen_random_uuid(),3,jsonb_build_array(jsonb_build_object('record_id',pg_temp.sid('record'),'status','excused','notes','Excused without sensitive details')),true,'Academic office review');
select is(public.attendance_sheet_details(pg_temp.sid('tenant'),pg_temp.sid('lesson'))->'sheet'->>'correction_count','1','Owner correction remains a separately recorded correction batch');
select is(public.attendance_sheet_details(pg_temp.sid('tenant'),pg_temp.sid('lesson'))->'sheet'->>'state','finalized','Correction preserves finalized state');
select ok(exists(select 1 from jsonb_array_elements(public.attendance_sheet_history(pg_temp.sid('tenant'),pg_temp.sid('lesson'))->'rows') x where x->>'record_id'=pg_temp.sid('record')::text and x->>'reason'='Academic office review' and x->'before_data'->>'status'='late' and x->'after_data'->>'status'='excused'),'Correction retains prior mark, new mark and required reason');
select throws_ok($$select public.transition_lesson(pg_temp.sid('tenant'),pg_temp.sid('lesson'),gen_random_uuid(),1,'cancelled','Unsafe cancellation')$$,'P0001','Finalized attendance prevents lesson cancellation or rescheduling','Finalized attendance cannot silently become a cancelled lesson');
select public.update_student_enrollment(pg_temp.sid('tenant'),pg_temp.sid('enrollment'),gen_random_uuid(),1,jsonb_build_object('status','withdrawn','effective_start_date',pg_temp.day(-10),'effective_end_date',pg_temp.day(0),'reason','Withdraw after attendance'));
select is(public.attendance_sheet_details(pg_temp.sid('tenant'),pg_temp.sid('lesson'))->'rows'->0->>'enrollment_id',pg_temp.sid('enrollment')::text,'Withdrawal retains the historical enrollment reference');
select is(public.attendance_record_directory(pg_temp.sid('tenant'),jsonb_build_object('from',pg_temp.day(-30),'to',pg_temp.day(0),'student',pg_temp.sid('student'),'status','excused','sheet','finalized'))->>'total','1','Basic student attendance history uses real saved marks');
select throws_ok($$delete from public.lesson_attendance_records where id=pg_temp.sid('record')$$,'42501',null,'Authenticated users cannot erase attendance history');
set local request.jwt.claim.sub='99999500-0000-0000-0000-000000000003';
select throws_ok($$select public.attendance_sheet_details(pg_temp.sid('tenant'),pg_temp.sid('lesson'))$$,'42501',null,'Foreign tenant lesson ID is rejected');
select is((select count(*) from public.lesson_attendance_records),0::bigint,'Foreign attendance RLS hides all rows');
set local request.jwt.claim.sub='';
select throws_ok($$select public.attendance_sheet_details(pg_temp.sid('tenant'),pg_temp.sid('lesson'))$$,'42501',null,'Subjectless requests cannot read attendance');
reset role;
select is((select count(*) from public.financial_ledger_entries where tenant_id=pg_temp.sid('tenant')),0::bigint,'Attendance does not post a financial ledger entry');
select is((select count(*) from public.invoice_receivable_entries where tenant_id=pg_temp.sid('tenant')),0::bigint,'Attendance creates no tuition receivable');
set constraints all immediate;
select * from finish();
rollback;
